"""Certificates for the escape family: sums of three positive cubes that no
choice of parameters in the Vieta identity can ever produce.

The residue-restricted box uses cube roots 6u+1, 6v+1, 6w+1 with
    1 <= u <= t^4,   4t^6 <= v < 8t^6,   34t^9 <= w < 68t^9,
so that the two nested greedy gap conditions still hold.  Since n^3 = n (mod 6),
every value is 3 (mod 6), while every Vieta value -3ab(a+b) is a multiple of 6.
Hence the 136 t^19 values of the box lie completely outside the Vieta value set.
"""

from __future__ import annotations

import random
from typing import Dict, Iterator, List, Tuple


def cube_gap(z: int) -> int:
    return 3 * z * z + 3 * z + 1


def escape_triples(t: int) -> Iterator[Tuple[int, int, int]]:
    for u in range(1, t**4 + 1):
        for v in range(4 * t**6, 8 * t**6):
            for w in range(34 * t**9, 68 * t**9):
                yield u, v, w


def escape_value(u: int, v: int, w: int) -> int:
    return (6 * u + 1) ** 3 + (6 * v + 1) ** 3 + (6 * w + 1) ** 3


def certify_escape(t: int) -> Dict[str, object]:
    values: Dict[int, Tuple[int, int, int]] = {}
    gaps_ok = True
    for u, v, w in escape_triples(t):
        big_x, big_y, big_z = 6 * u + 1, 6 * v + 1, 6 * w + 1
        if not (big_x**3 < cube_gap(big_y)
                and big_x**3 + big_y**3 < cube_gap(big_z)):
            gaps_ok = False
        n = escape_value(u, v, w)
        values[n] = (u, v, w)
    count = sum(1 for _ in escape_triples(t))
    return {
        "t": t,
        "triples": count,
        "predicted 136 t^19": 136 * t**19,
        "distinct values": len(values),
        "injective": len(values) == count,
        "gap conditions": gaps_ok,
        "max value": max(values),
        "bound 10^8 t^27": 10**8 * t**27,
        "residues mod 6": sorted({n % 6 for n in values}),
        "any multiple of 6": any(n % 6 == 0 for n in values),
    }


def certify_escape_sampled(t: int, samples: int = 20000, seed: int = 1) -> Dict[str, object]:
    """Random-sample certification for a scale t too large to enumerate."""
    rng = random.Random(seed)
    seen: Dict[int, Tuple[int, int, int]] = {}
    gaps_ok = True
    bound_ok = True
    for _ in range(samples):
        u = rng.randrange(1, t**4 + 1)
        v = rng.randrange(4 * t**6, 8 * t**6)
        w = rng.randrange(34 * t**9, 68 * t**9)
        big_x, big_y, big_z = 6 * u + 1, 6 * v + 1, 6 * w + 1
        if not (big_x**3 < cube_gap(big_y)
                and big_x**3 + big_y**3 < cube_gap(big_z)):
            gaps_ok = False
        n = escape_value(u, v, w)
        if n > 10**8 * t**27:
            bound_ok = False
        if n in seen and seen[n] != (u, v, w):
            raise AssertionError("collision detected")
        seen[n] = (u, v, w)
    return {
        "t": t,
        "sampled triples": samples,
        "distinct values": len(seen),
        "gap conditions": gaps_ok,
        "within 10^8 t^27": bound_ok,
        "residues mod 6": sorted({n % 6 for n in seen}),
    }


def brute_force_vieta_hit(n: int) -> bool:
    """Search exhaustively for integers a, b with -3ab(a+b) = n (n > 0)."""
    limit = 1 + int(abs(n) ** (1 / 3)) * 4
    for a in range(-limit, limit + 1):
        for b in range(-limit, limit + 1):
            if -3 * a * b * (a + b) == n:
                return True
    return False


def main() -> None:
    for t in (1,):
        print(f"--- t = {t} (exhaustive certification) ---")
        for key, value in certify_escape(t).items():
            print(f"  {key:>20}: {value}")
        print()

    print("--- t = 5 (random-sample certification; the full box has "
          f"{136 * 5**19} points) ---")
    for key, value in certify_escape_sampled(5).items():
        print(f"  {key:>20}: {value}")
    print()

    print("Independent brute-force check that a few escape values are unreachable:")
    samples: List[int] = sorted(escape_value(*p) for p in escape_triples(1))[:4]
    for n in samples:
        print(f"  n = {n:>12}  n mod 6 = {n % 6}  "
              f"Vieta representation found: {brute_force_vieta_hit(n)}")


if __name__ == "__main__":
    main()

